// Array initialization
// -----------------------------------------------------------------------------
// Original semantics:
//   for i in [0, n)
//     for j in [0, n)
//       A[i,j] = (i*(j+2)+2)/n
//       B[i,j] = (i*(j+3)+3)/n
//
// Optimizations:
//   - Compute n only once outside the traversal.
//   - Replace division by n with multiplication by precomputed 1/n.
//   - Capture all values by reference to avoid copying the bags into the lambda.
void init_array(auto A, auto B) {
	using namespace noarr;

	const std::size_t n = A | get_length<'i'>();
	const num_t inv_n = num_t(1) / num_t(n); // precompute reciprocal to avoid per-element division

	// A, B: i x j
	traverser(A, B).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		const num_t fi = static_cast<num_t>(i);
		const num_t fj = static_cast<num_t>(j);

		A[state] = (fi * (fj + num_t(2)) + num_t(2)) * inv_n;
		B[state] = (fi * (fj + num_t(3)) + num_t(3)) * inv_n;
	});
