// Original semantics (polybench Jacobi-2d):
//   for t in [0, tsteps)
//     B := stencil(A)
//     A := stencil(B)
//
// Stencil:
//   X[i,j] = 0.2 * (X[i,j] + X[i,j-1] + X[i,j+1] + X[i-1,j] + X[i+1,j])
