// Optimizations:
//   - Precompute n and inner_len once.
//   - Build the "interior" traversal (i,j in [1, n-2]) once and reuse it for all time steps.
//   - Use references in lambdas (capture [&]) to avoid copying bags each time.
//   - Hoist the constant 0.2 into a named variable.
//   - Load neighbor values into local variables to avoid repeating address computation.
//
// Loops are still expressed exclusively via Noarr traversers and index states.
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_2d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// A, B: i x j
	const std::size_t n = A | get_length<'i'>();
	const std::size_t inner_len = n - 2; // number of interior points in each dimension

	const num_t c0_2 = num_t(0.2); // stencil coefficient

