			auto west  = state - idx<'j'>(1);
			auto east  = state + idx<'j'>(1);
			auto south = state + idx<'i'>(1);
			auto north = state - idx<'i'>(1);

			const num_t c  = B[state];
			const num_t wv = B[west];
			const num_t ev = B[east];
			const num_t sv = B[south];
			const num_t nv = B[north];

