// Optimization notes:
//  - We pre-build an "interior" traverser that visits only the interior points
//    (1..n-2 in both dimensions). This avoids recreating the sliced traverser
//    every time step.
//  - We traverse A and B together using a single traverser(A,B) object, which
//    improves cache locality of meta-data and avoids recomputing lengths.
//  - We precompute the index-state offsets for the four neighbors (±1 in 'i'
//    and 'j') so that the per-point stencil only does additions/subtractions
//    on states, not re-creating idx<...>() each time.
//  - We explicitly cache the five A / B values into local scalars before
//    forming the stencil result, to minimize repeated address computations
//    and allow the compiler to better optimize / vectorize the loop.
//
// Semantics are unchanged: for each time step t, we first compute B := stencil(A)
// on the interior, then A := stencil(B) on the same interior.
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_2d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// A, B: i x j
	const std::size_t n = A | get_length<'i'>();
	const std::size_t inner_len = n - 2; // number of interior points in each dimension

	// Constant factor for the 5-point stencil
	const num_t c0_2 = (num_t)0.2;

	// Precompute neighbor displacements in the index space
	const auto di = idx<'i'>(1); // (+1 in i)
	const auto dj = idx<'j'>(1); // (+1 in j)

