	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ i_vec);
} tuning;

/**
 * Parallel helper for traversers.
 *
 * It splits the top-most traversed dimension into independent
 * sub-traversers and then runs `for_each` on each of them.  With OpenMP
 * enabled, the outer loop is parallel; otherwise the pragma is ignored
 * and this degrades to a plain serial loop.
 *
 * The kernel itself is still expressed purely with noarr traversers and
 * index states as required.
 */
template<typename Traverser, typename Func>
inline void parallel_for_each_traverser(const Traverser &trav, const Func &func) {
	// NOTE:
	// - Each `sub_trav` has a disjoint slice of the original structure.
	// - The lambda `func` must therefore not carry cross-iteration
	//   dependencies; this holds for both `init_array` and the Jacobi
	//   stencil sweeps below.
	#pragma omp parallel for
	for (auto sub_trav : trav) {
		sub_trav.for_each(func);
	}
}

// Array initialization
void init_array(auto A, auto B) {
	using namespace noarr;

	// A, B: i x j
	const auto n = A | get_length<'i'>();

	// Traverse both arrays in lock-step so that each (i,j) is touched once.
	auto init_trav = traverser(A, B);

	parallel_for_each_traverser(init_trav, [=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		A[state] = ((num_t)i * (num_t)(j + 2) + (num_t)2) / (num_t)n;
		B[state] = ((num_t)i * (num_t)(j + 3) + (num_t)3) / (num_t)n;
	});
}


// Main computational kernel
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_2d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// A, B: i x j
	const auto n = A | get_length<'i'>();
	const auto inner_len = n - 2; // number of interior points in each dimension

	// Proto-structure describing the interior (i,j) \in [1, n-2] × [1, n-2].
	// This is reused for both sweeps to avoid rebuilding it in each loop.
	const auto interior =
		noarr::slice<'i'>(1, inner_len) ^
		noarr::slice<'j'>(1, inner_len);

	constexpr num_t w = (num_t)0.2; // stencil weight, common to both sweeps

#pragma scop
	for (int t = 0; t < tsteps; t++) {
		// First sweep: B := stencil(A)
		//
		// We iterate only over interior points; the boundary values
		// stay unchanged throughout the whole computation.
		auto trav_A = traverser(A).order(interior);

		parallel_for_each_traverser(trav_A, [&](auto state) {
			// Neighbor index states (pure state arithmetic, no traverser arithmetic)
			auto west  = state - idx<'j'>(1);
			auto east  = state + idx<'j'>(1);
			auto south = state + idx<'i'>(1);
			auto north = state - idx<'i'>(1);

			const num_t center = A[state];
			const num_t sum =
				center +
				A[west] +
				A[east] +
				A[south] +
				A[north];

			B[state] = w * sum;
		});

		// Second sweep: A := stencil(B)
		auto trav_B = traverser(B).order(interior);

		parallel_for_each_traverser(trav_B, [&](auto state) {
			auto west  = state - idx<'j'>(1);
			auto east  = state + idx<'j'>(1);
			auto south = state + idx<'i'>(1);
			auto north = state - idx<'i'>(1);

			const num_t center = B[state];
			const num_t sum =
				center +
				B[west] +
				B[east] +
				B[south] +
				B[north];

			A[state] = w * sum;
		});
	}
#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// set lengths of dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// allocate data
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize arrays
