#include "jacobi-2d.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A and B are N x N with C-style row-major layout: i = row, j = column
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(b_layout, j_vec ^ i_vec);
} tuning;


// Array initialization
// ------------------------------------------------------------------
// Optimizations:
//  - Pull the grid size `n` out of the per-element lambda
//  - Optionally parallelize over the outer 'i' dimension using OpenMP
//    while still using Noarr traversers for the spatial loops.
void init_array(auto A, auto B) {
	using namespace noarr;

	// A, B: i x j
	const std::size_t n = A | get_length<'i'>();
	const num_t inv_n = num_t(1) / num_t(n);

	auto trav = traverser(A, B);

#if defined(_OPENMP)
	// Split the traverser along the outer 'i' dimension to get rows
	auto row_range = trav.template range<'i'>();

	#pragma omp parallel for schedule(static)
	for (std::size_t i_index = row_range.begin_idx; i_index < row_range.end_idx; ++i_index) {
		auto row_trav = row_range[i_index]; // traverser with fixed 'i', iterates over 'j'

		row_trav.for_each([=](auto state) {
			auto [i, j] = get_indices<'i', 'j'>(state);

			// Polybench initialization formulas
			A[state] = ( (num_t)i * (num_t)(j + 2) + num_t(2) ) * inv_n;
			B[state] = ( (num_t)i * (num_t)(j + 3) + num_t(3) ) * inv_n;
		});
	}
#else
	trav.for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		A[state] = ( (num_t)i * (num_t)(j + 2) + num_t(2) ) / num_t(n);
		B[state] = ( (num_t)i * (num_t)(j + 3) + num_t(3) ) / num_t(n);
	});
#endif
}


// Main computational kernel
// ------------------------------------------------------------------
// Jacobi 2D, 5-point stencil on the interior (1 .. N-2) x (1 .. N-2).
//
// Optimizations:
//  - Precompute the proto-structure that describes the interior once,
//    instead of recreating slices every time step.
//  - Factor the stencil application into a reusable lambda
//    `apply_stencil(src, dst)` to avoid code duplication.
//  - Optionally parallelize each sweep over the outer 'i' dimension
//    using OpenMP and traverser ranges; within each row we still use
//    Noarr's for_each over 'j'. This preserves the original semantics
//    while improving multi-core utilization.
//  - The spatial iteration order is still row-major (i outer, j inner),
//    so cache-friendliness and vectorization opportunities are kept.
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_2d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// A, B: i x j
	const std::size_t n = A | get_length<'i'>();
	const std::size_t inner_len = n - 2; // number of interior points in each dimension

	// View of the interior region [1..n-2] x [1..n-2].
	// Built once and reused across all time steps.
	const auto interior =
		noarr::slice<'i'>(1, inner_len) ^
		noarr::slice<'j'>(1, inner_len);

	// Apply one Jacobi sweep: dst := stencil(src)
	auto apply_stencil = [&](auto &src, auto &dst) {
		auto trav = traverser(src).order(interior);

#if defined(_OPENMP)
		// Parallelize over the outer 'i' dimension.
		// Each thread gets a distinct band of rows, so writes into `dst`
		// are disjoint between threads. `src` is read-only in this sweep.
		auto row_range = trav.template range<'i'>();

		#pragma omp parallel for schedule(static)
		for (std::size_t i_index = row_range.begin_idx; i_index < row_range.end_idx; ++i_index) {
			auto row_trav = row_range[i_index]; // 'i' fixed, iterates over 'j'

			row_trav.for_each([&](auto state) {
				// Neighbour states around (i,j)
				auto west  = state - idx<'j'>(1);
				auto east  = state + idx<'j'>(1);
				auto south = state + idx<'i'>(1);
				auto north = state - idx<'i'>(1);

				// 5-point stencil
				dst[state] = num_t(0.2) * (
					src[state] +
					src[west] +
					src[east] +
					src[south] +
					src[north]
				);
			});
		}
#else
		trav.for_each([&](auto state) {
			auto west  = state - idx<'j'>(1);
			auto east  = state + idx<'j'>(1);
			auto south = state + idx<'i'>(1);
			auto north = state - idx<'i'>(1);

			dst[state] = num_t(0.2) * (
				src[state] +
				src[west] +
				src[east] +
				src[south] +
				src[north]
			);
		});
#endif
	};

#pragma scop
	for (int t = 0; t < tsteps; t++) {
		// First sweep: B := stencil(A)
		apply_stencil(A, B);

		// Second sweep: A := stencil(B)
		apply_stencil(B, A);
	}
#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t tsteps = TSTEPS;

	// set lengths of dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// allocate data
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_jacobi_2d((int)tsteps, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
